{
  "requirement_id": "SFMC-REQ-030",
  "raw_text": "The SFMC shall immediately notify the pilot of all critical faults.",
  "software_requirement_status": "YES",
  "quality_status": "NEEDS_REVIEW",
  "quality_issues": [
    {
      "issue_code": "UNDEFINED_TERM",
      "severity": "MAJOR",
      "explanation": "The term 'critical faults' is not defined within the SRS. Section 11 Open Items explicitly lists 'Definition of critical fault' as unresolved, which is essential for clarity and testability of this requirement.",
      "srs_evidence": [
        {
          "locator": "Section 11 Open Items",
          "excerpt": "3. Definition of a critical fault."
        },
        {
          "locator": "Section 3.6 Vehicle Health Monitoring",
          "excerpt": "SFMC-REQ-030 — Critical Faults\nThe SFMC shall immediately notify the pilot of all critical faults."
        }
      ],
      "nasa_references": [
        {
          "document": "NASA-HDBK-2203-5.09",
          "authority": "HANDBOOK_GUIDANCE",
          "section": "§3.2.1.9",
          "swe_id": null,
          "url": "https://swehb.nasa.gov/spaces/SWEHBVD/pages/102695669/5.09+-+SRS+-+Software+Requirements+Specification"
        }
      ],
      "recommendation": "Define 'critical fault' explicitly in the SRS to ensure unambiguous understanding and verifiability of the requirement.",
      "requires_stakeholder_input": true
    },
    {
      "issue_code": "MISSING_ACCEPTANCE_CRITERIA",
      "severity": "MAJOR",
      "explanation": "The requirement states 'immediately notify' but does not specify timing constraints or the method of notification, which are necessary for verification and validation.",
      "srs_evidence": [
        {
          "locator": "Section 3.6 Vehicle Health Monitoring",
          "excerpt": "SFMC-REQ-030 — Critical Faults\nThe SFMC shall immediately notify the pilot of all critical faults."
        }
      ],
      "nasa_references": [
        {
          "document": "NASA-HDBK-2203-5.09",
          "authority": "HANDBOOK_GUIDANCE",
          "section": "§3.2.1.9",
          "swe_id": null,
          "url": "https://swehb.nasa.gov/spaces/SWEHBVD/pages/102695669/5.09+-+SRS+-+Software+Requirements+Specification"
        }
      ],
      "recommendation": "Specify measurable notification timing and methods (e.g., display update latency, audible alarm) to enable verification.",
      "requires_stakeholder_input": true
    }
  ],
  "primary_swe_id": null,
  "primary_swe_strength": null,
  "swe_links": [],
  "summary": "SFMC-REQ-030 is a valid software requirement addressing fault notification to the pilot. However, it lacks a clear definition of 'critical faults' and measurable acceptance criteria for 'immediate' notification. These deficiencies reduce clarity and verifiability, requiring stakeholder input to resolve. No direct NPR SWE linkage is justified based on the supplied evidence."
}
